 v_ids text[];
 v_count integer;
 v_before_other text;
 v_after_other text;
begin
 select array_agg(x.entity_id) into v_ids from jsonb_to_recordset(v_expected) x(entity_id text);
 if cardinality(v_ids)<>18 then raise exception 'Expected exactly 18 company IDs'; end if;
 if not exists(select 1 from public.aitask_members where workspace_id=v_workspace and id=v_target and name='Ting Ting' and role='Project Manager' and not is_super_admin) then raise exception 'Ting Ting PM identity did not match'; end if;
 if exists(select 1 from public.aitask_audit_events where command_id=v_command) then raise exception 'Transfer operation already recorded'; end if;
 perform 1 from public.aitask_workspaces where id=v_workspace for update;
 if not found then raise exception 'Workspace missing'; end if;
 perform e.entity_id from public.aitask_entities e where e.workspace_id=v_workspace and e.entity_type='client' and e.entity_id=any(v_ids) order by e.entity_id for update;
 select count(*) into v_count from public.aitask_entities e join jsonb_to_recordset(v_expected) x(entity_id text,version bigint,data jsonb) on x.entity_id=e.entity_id where e.workspace_id=v_workspace and e.entity_type='client' and e.created_by='u-boss' and e.data->>'createdBy'='u-boss' and e.version=x.version and e.data=x.data;
 if v_count<>18 then raise exception 'Company owner/version/data changed; transfer aborted'; end if;
 select md5(coalesce(string_agg(to_jsonb(e)::text,'|' order by e.entity_type,e.entity_id),'empty')) into v_before_other from public.aitask_entities e where e.workspace_id=v_workspace and not(e.entity_type='client' and e.entity_id=any(v_ids));
 update public.aitask_entities e
 set data=e.data||jsonb_build_object('createdBy',v_target,'updatedAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),version=e.version+1,updated_at=now()
 where e.workspace_id=v_workspace and e.entity_type='client' and e.entity_id=any(v_ids);
 get diagnostics v_count=row_count;
 if v_count<>18 then raise exception 'Unexpected updated company count: %',v_count; end if;
 if exists(select 1 from public.aitask_entities e join jsonb_to_recordset(v_expected) x(entity_id text,version bigint,data jsonb) on x.entity_id=e.entity_id where e.workspace_id=v_workspace and e.entity_type='client' and (e.created_by is distinct from v_target or e.data->>'createdBy' is distinct from v_target or e.version<>x.version+1 or (e.data-'createdBy'-'updatedAt') is distinct from (x.data-'createdBy'-'updatedAt'))) then raise exception 'Transferred company verification failed'; end if;
 insert into public.aitask_audit_events(workspace_id,actor_member_id,command_id,action,entity_type,entity_id,changed_fields,metadata)
 select v_workspace,null,v_command,'update','client',x.entity_id,array['createdBy','updatedAt'],jsonb_build_object('source','codex_user_authorized_admin_correction','reason','User explicitly requested transferring these previously identified 18 companies from Boss Koo to Ting Ting.','previousOwner','u-boss','newOwner',v_target,'previousVersion',x.version,'newVersion',x.version+1,'beforeData',x.data)
 from jsonb_to_recordset(v_expected) x(entity_id text,version bigint,data jsonb);
 update public.aitask_workspaces set version=version+1,updated_at=now() where id=v_workspace;
 select md5(coalesce(string_agg(to_jsonb(e)::text,'|' order by e.entity_type,e.entity_id),'empty')) into v_after_other from public.aitask_entities e where e.workspace_id=v_workspace and not(e.entity_type='client' and e.entity_id=any(v_ids));
 if v_after_other is distinct from v_before_other then raise exception 'Non-target entities changed; transaction aborted'; end if;
end
$transfer$;
commit;
select jsonb_build_object('operation_id','be2b5e43-c6a1-4a5a-a9e5-b8685cf9de01','transferred',(select count(*) from public.aitask_audit_events where command_id='be2b5e43-c6a1-4a5a-a9e5-b8685cf9de01'::uuid),'companies',(select jsonb_agg(jsonb_build_object('id',e.entity_id,'company',e.data->>'clientName','owner',e.created_by,'version',e.version) order by e.data->>'clientName') from public.aitask_entities e where e.workspace_id='aitask-main' and e.entity_type='client' and e.entity_id in ('CL-migrated-3119cb1dbc4835616f61a492','CL-migrated-359522d284a5390c46626234','CL-migrated-4bdfcb624924c9d8ba55cb55','CL-migrated-5b405651490d6366be87592a','CL-migrated-5f64c8045f78f8cba369003d','CL-migrated-70fc3eb646f2255c2b1b44eb','CL-migrated-782b430ae93bf70f1903f569','CL-migrated-892d50cdbb919677cd84cb08','CL-migrated-8fab853443aa0f861ea3586a','CL-migrated-aab5e7a3ed5b7806c5f2f2e4','CL-migrated-ae560e357ef62b5819657b6d','CL-migrated-b54ea4eede9a954d1795e73c','CL-migrated-c5039ad9c12a3cb569964081','CL-migrated-ca0f5f90ef46343f4d2b8080','CL-migrated-e5a5e81d368e2c4b2b57e0a3','CL-migrated-e7e7eb037df321863a3fcaa1','CL-migrated-f0fd0686011d036206ca8402','CL-migrated-ffb238e303d7773396608ff7')),'workspace_version',(select version from public.aitask_workspaces where id='aitask-main')) as transfer_result;
